insert into platform_modules(code,title,is_active) values ('42-document-approvals','گردش تأیید و انتشار مستندات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده گردش‌ها','modules:42-document-approvals:read'),('write','ایجاد و ویرایش گردش','modules:42-document-approvals:write'),('delete','حذف گردش','modules:42-document-approvals:delete'),('submit','ارسال برای بازبینی','modules:42-document-approvals:submit'),('review','ثبت بازبینی','modules:42-document-approvals:review'),('approve','تأیید انتشار','modules:42-document-approvals:approve'),('reject','رد گردش','modules:42-document-approvals:reject'),('cancel','لغو گردش','modules:42-document-approvals:cancel')) v(a,t,p) where m.code='42-document-approvals' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;