select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('approval-code','کد گردش','text',true,10,'{}'),('document-code','کد سند','text',true,20,'{}'),('document-title','عنوان سند','text',true,30,'{}'),('document-version','نسخه سند','number',true,40,'{}'),('workflow-type','نوع گردش','select',true,50,'{"options":["بازبینی محتوا","تأیید انتشار","تأیید اصلاحات","ابطال سند","بازبینی دوره‌ای"]}'),('requester','درخواست‌کننده','text',true,60,'{}'),('reviewer','بازبین','text',false,70,'{}'),('approver','تأییدکننده','text',false,80,'{}'),('request-date','تاریخ درخواست','text',true,90,'{}'),('review-date','تاریخ بازبینی','text',false,100,'{}'),('decision-date','تاریخ تصمیم','text',false,110,'{}'),('decision','نتیجه تصمیم','select',false,120,'{"options":["تأیید","تأیید مشروط","رد","نیازمند اصلاح"]}'),('status','وضعیت گردش','select',true,130,'{"options":["پیش‌نویس","در انتظار بازبینی","در انتظار تأیید","تأیید شده","رد شده","نیازمند اصلاح","لغو شده"]}'),('priority','اولویت','select',true,140,'{"options":["عادی","مهم","فوری","بحرانی"]}'),('comments','نظر بازبین','textarea',false,150,'{}'),('conditions','شرایط تأیید','textarea',false,160,'{}'),('next-review-date','تاریخ بازبینی بعدی','text',false,170,'{}'),('audit-reference','مرجع ثبت رویداد','text',false,180,'{}'),('notes','یادداشت','textarea',false,190,'{}')
) v(k,t,ft,r,s,o) where m.code='42-document-approvals' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
